  for (int num : nums) {
    hashMap.put(num, hashMap.getOrDefault(num, 0) + 1);
  }

  int sum = 0;
  for (int key : hashMap.keySet()) {
    if (hashMap.get(key) == 1) {
      sum += key;
    }
  }

  return sum;
}

